INSERT INTO `rsns_custom_logistik_non_medis_kategori` VALUES (1,'KAT-001','Alat HK','Alat housekeeping: pel, sapu, kemoceng, sikat, ember, keset, gayung'),(2,'KAT-002','Alat Tulis Kantor','Kertas, buku, alat tulis, formulir rekam medis, dan kebutuhan cetak.'),(3,'KAT-003','Cetakan & Form','Formulir cetak RS, blanko, resep, kwitansi, label, register'),(4,'KAT-004','Elektronik & IT','Komputer, printer, tinta, perangkat jaringan, dan peralatan elektronik.'),(5,'KAT-005','flowchart','flowchart icu & picu nicu'),(6,'KAT-006','Fotocopy','Fototcopy'),(7,'KAT-007','Jenis Kertas','Kertas HVS, A4, F4, kertas potong, kwarto, kertas thermal, buffalo'),(8,'KAT-008','Linen & Seragam','Sprei, sarung bantal, selimut, handuk, dan kain gorden.'),(9,'KAT-009','Liquid','Cairan: karbol sereh, karbol, heviklir, detergen liquid, softener, pencuci piring, pembersih lantai'),(10,'KAT-010','Plastik','Kantong plastik sampah hitam, kuning, kresek, plastik laundry'),(11,'KAT-011','Rumah Tangga & Kebersihan','Sabun, deterjen, tissue, alat pel, dan perlengkapan sanitasi.'),(12,'KAT-012','Tinta','tinta printer, tinta stample'),(54,'KAT-014','Bahan Bakar & Pelumas','Solar genset, bensin, oli mesin, dan pelumas peralatan.'),(55,'KAT-015','Kendaraan & Suku Cadang','Ban, filter, aki, dan suku cadang armada ambulans/operasional.'),(56,'KAT-016','Perlengkapan Kantor','Meja, kursi, lemari arsip, dan furnitur kantor lainnya.'),(57,'KAT-017','Linen & Perlengkapan Pasien','Sprei, sarung bantal, selimut, handuk, dan kain gorden.'),(58,'KAT-018','Alat Listrik & Penerangan','Lampu, kabel, saklar, baterai, dan komponen kelistrikan.'),(59,'KAT-019','Bahan Bangunan & Pemeliharaan','Cat, semen, kunci pintu, kran air, dan material pemeliharaan gedung.'),(60,'KAT-020','Gas Medis & Oksigen','Tabung O2, N2O, CO2, serta regulator dan aksesoris gas medis.'),(61,'KAT-021','Bahan Makanan & Gizi','Beras, minyak goreng, bumbu dapur, dan bahan makanan kering.'),(62,'KAT-022','Seragam & Atribut Karyawan','Baju dinas, sepatu kerja, name tag, dan atribut seragam lainnya.');
